def _R_from_h(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[1:-1] = c
    L[-1] = 0.0
    L2 = L * L
    Lp = L[1:]
    Lm = L[:-1]
    num = np.sum(L2 + Lm * Lp + Lp * Lp) / 3.0
    mass = np.sum(h)
    denom = (mass * mass) * np.max(L)
    if denom <= 0:
        return 0.0
    return num / denom


