def _R_from_h(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    # ||f*f||_2^2
    l2sq = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7

    N = 512
    j = np.arange(N, dtype=float)
    x = np.pi * j / (N - 1)  # 0..pi

    # Precompute cos basis for speed
    def make_h(a):
        # a: [a0, a1..a6]
        val = a[0] + sum(a[k] * np.cos(k * x) for k in range(1, 7))
        return np.exp(val)

    best = {"R": -1.0, "a": None}

    def obj(a):
        if time.process_time() > deadline:
            raise TimeoutError
        h = make_h(a)
        r = _R_from_h(h)
        if r > best["R"]:
            best["R"] = r
            best["a"] = np.array(a, dtype=float)
        return -r

    # Seed best with start if provided
    if start is not None:
        s = np.asarray(start, dtype=float)
        r0 = _R_from_h(s)
        if r0 > best["R"]:
            best["R"] = r0
            best["a"] = None  # marker: use start directly

    bounds = [(-2.0, 2.0)] * 7
    try:
        differential_evolution(
            obj, bounds, maxiter=1000, popsize=15, tol=1e-8,
            polish=False, seed=12345, init='sobol',
        )
    except TimeoutError:
        pass

    # Nelder-Mead refinement
    if best["a"] is not None:
        try:
            minimize(obj, best["a"], method='Nelder-Mead',
                     options={'maxiter': 2000, 'xatol': 1e-8, 'fatol': 1e-12})
        except TimeoutError:
            pass
    else:
        # start was best; try refining around a flat-ish init
        try:
            minimize(obj, np.zeros(7), method='Nelder-Mead',
                     options={'maxiter': 2000, 'xatol': 1e-8, 'fatol': 1e-12})
        except TimeoutError:
            pass

    if best["a"] is not None:
        h = make_h(best["a"])
        if _R_from_h(h) >= best["R"] - 1e-12:
            return h

    if start is not None:
        return np.asarray(start, dtype=float)
    return np.ones(50)

