    return l2sq / (l1 * linf)


def _R_and_grad_z(z, p=20.0):
    h = z * z
    s = h.sum()
    conv = np.convolve(h, h)
    L = np.concatenate(([0.0], conv, [0.0]))
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s

    Lp = np.maximum(L, 0.0)
    Lp_pow = Lp ** p
    sum_pow = Lp_pow.sum()
    if sum_pow <= 0:
        return -1.0, np.zeros_like(z)
    linf = sum_pow ** (1.0 / p)
    R = num / (l1 * linf)

    dnum = np.zeros_like(L)
    dnum[:-1] += (2 * a + b) / 3.0
    dnum[1:] += (a + 2 * b) / 3.0
    dR_dL = dnum / (l1 * linf)
    dlinf_dL = linf * (Lp ** (p - 1.0)) / sum_pow
    dR_dL -= num / (l1 * linf * linf) * dlinf_dL
    dR_dconv = dR_dL[1:-1]
    grad_h = 2.0 * np.correlate(dR_dconv, h, mode='valid')
    grad_h += -2.0 * R / s
    grad_z = 2.0 * z * grad_h
    return R, grad_z


def _lbfgs(z_init, maxiter=400, ftol=1e-15, p=20.0, maxfun=None):
    def fun(z):
        R, g = _R_and_grad_z(z, p=p)
        return -R, -g
    opts = {'maxiter': maxiter, 'ftol': ftol, 'gtol': 1e-11}
    if maxfun is not None:
        opts['maxfun'] = maxfun
    try:
        res = minimize(fun, z_init, jac=True, method='L-BFGS-B', options=opts)
        return res.x, -res.fun
    except Exception:
        return z_init, _R_from_h(z_init * z_init)


